    /// <summary>
    /// 定义点交叉校验：本文件常量 vs <see cref="Abi"/> 数据表。null = 一致；
    /// 非 null = 首条不符的说明。表长变化亦在此暴露（生成物按当时表长展开）。
    /// </summary>
    public static string? Verify()
    {
        if (Abi.Scalars.Length != 20) return "Abi.Scalars 表长与生成物不符";
        if (Abi.Scalars[0].Value != FgbMagic) return "标量 FgbMagic 与生成物不符";
        if (Abi.Scalars[1].Value != FgbFormatVersion) return "标量 FgbFormatVersion 与生成物不符";
        if (Abi.Scalars[2].Value != FgbSectionAlignment) return "标量 FgbSectionAlignment 与生成物不符";
        if (Abi.Scalars[3].Value != QuadInstanceSize) return "标量 QuadInstanceSize 与生成物不符";
        if (Abi.Scalars[4].Value != QuadInstanceAlignment) return "标量 QuadInstanceAlignment 与生成物不符";
        if (Abi.Scalars[5].Value != ClipEntrySize) return "标量 ClipEntrySize 与生成物不符";
        if (Abi.Scalars[6].Value != ClipEntryAlignment) return "标量 ClipEntryAlignment 与生成物不符";
        if (Abi.Scalars[7].Value != SegmentMaxTextures) return "标量 SegmentMaxTextures 与生成物不符";
        if (Abi.Scalars[8].Value != PaintOrderStride) return "标量 PaintOrderStride 与生成物不符";
        if (Abi.Scalars[9].Value != ShaderAbiVersion) return "标量 ShaderAbiVersion 与生成物不符";
        if (Abi.Scalars[10].Value != TransformSlotBudget) return "标量 TransformSlotBudget 与生成物不符";
        if (Abi.Scalars[11].Value != ClipEntryBudget) return "标量 ClipEntryBudget 与生成物不符";
        if (Abi.Scalars[12].Value != GpuFenceDepth) return "标量 GpuFenceDepth 与生成物不符";
        if (Abi.Scalars[13].Value != MaxObservableProps) return "标量 MaxObservableProps 与生成物不符";
        if (Abi.Scalars[14].Value != CommandWaveLimit) return "标量 CommandWaveLimit 与生成物不符";
        if (Abi.Scalars[15].Value != LayoutMicroDrainLimit) return "标量 LayoutMicroDrainLimit 与生成物不符";
        if (Abi.Scalars[16].Value != FgbHeaderSize) return "标量 FgbHeaderSize 与生成物不符";
        if (Abi.Scalars[17].Value != FgbSectionDirEntrySize) return "标量 FgbSectionDirEntrySize 与生成物不符";
        if (Abi.Scalars[18].Value != NodeBytesPerNode) return "标量 NodeBytesPerNode 与生成物不符";
        if (Abi.Scalars[19].Value != FgbInstanceHeaderBytes) return "标量 FgbInstanceHeaderBytes 与生成物不符";
        if (Abi.QuadInstanceFields.Length != 8) return "Abi.QuadInstanceFields 表长与生成物不符";
        if (Abi.QuadInstanceFields[0].Offset != QuadRectOffset || Abi.QuadInstanceFields[0].Size != QuadRectSize) return "QuadRect 偏移/大小与生成物不符";
        if (Abi.QuadInstanceFields[1].Offset != QuadUvAOffset || Abi.QuadInstanceFields[1].Size != QuadUvASize) return "QuadUvA 偏移/大小与生成物不符";
        if (Abi.QuadInstanceFields[2].Offset != QuadUvBOffset || Abi.QuadInstanceFields[2].Size != QuadUvBSize) return "QuadUvB 偏移/大小与生成物不符";
        if (Abi.QuadInstanceFields[3].Offset != QuadColorOffset || Abi.QuadInstanceFields[3].Size != QuadColorSize) return "QuadColor 偏移/大小与生成物不符";
        if (Abi.QuadInstanceFields[4].Offset != QuadRouteOffset || Abi.QuadInstanceFields[4].Size != QuadRouteSize) return "QuadRoute 偏移/大小与生成物不符";
        if (Abi.QuadInstanceFields[5].Offset != QuadFlagsOffset || Abi.QuadInstanceFields[5].Size != QuadFlagsSize) return "QuadFlags 偏移/大小与生成物不符";
        if (Abi.QuadInstanceFields[6].Offset != QuadAuxOffset || Abi.QuadInstanceFields[6].Size != QuadAuxSize) return "QuadAux 偏移/大小与生成物不符";
        if (Abi.QuadInstanceFields[7].Offset != QuadExtraOffset || Abi.QuadInstanceFields[7].Size != QuadExtraSize) return "QuadExtra 偏移/大小与生成物不符";
        if (Abi.ClipEntryFields.Length != 5) return "Abi.ClipEntryFields 表长与生成物不符";
        if (Abi.ClipEntryFields[0].Offset != ClipRectOffset || Abi.ClipEntryFields[0].Size != ClipRectSize) return "ClipRect 偏移/大小与生成物不符";
        if (Abi.ClipEntryFields[1].Offset != ClipSoftOffset || Abi.ClipEntryFields[1].Size != ClipSoftSize) return "ClipSoft 偏移/大小与生成物不符";
        if (Abi.ClipEntryFields[2].Offset != ClipRadiiOffset || Abi.ClipEntryFields[2].Size != ClipRadiiSize) return "ClipRadii 偏移/大小与生成物不符";
        if (Abi.ClipEntryFields[3].Offset != ClipSlotOffset || Abi.ClipEntryFields[3].Size != ClipSlotSize) return "ClipSlot 偏移/大小与生成物不符";
