        if (Abi.RouteBits.Length != 4) return "Abi.RouteBits 表长与生成物不符";
        if (Abi.RouteBits[0].Shift != RouteSlotShift || Abi.RouteBits[0].Width != RouteSlotBits) return "RouteSlot 位域与生成物不符";
